-- =====================================================================
--  PonteChetado - Avatar (Historias 009 y 010) y Chatbot (Historia 011)
--  Ejecutar en MySQL Workbench con el botón del rayo.
--  Se puede volver a ejecutar sin problemas: no duplica nada.
--  Archivo generado automáticamente.
-- =====================================================================

USE pontechetado;
SET NAMES utf8mb4;

-- ---------------------------------------------------------------------
-- Avatar: lo que eligió cada usuario. Los números son posiciones en las
-- paletas de la app (piel 0-4, peinado 0-3, pelo 0-5, ropa 0-5).
-- La evolución (muñequeras, cintillo, medalla, corona) depende del nivel,
-- que se calcula con la XP, así que no se guarda aquí.
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS avatares (
    usuario_id      INT NOT NULL PRIMARY KEY,
    genero          ENUM('masculino', 'femenino') NOT NULL DEFAULT 'masculino',
    piel            TINYINT NOT NULL DEFAULT 1,
    peinado         TINYINT NOT NULL DEFAULT 0,
    color_pelo      TINYINT NOT NULL DEFAULT 0,
    color_ropa      TINYINT NOT NULL DEFAULT 0,
    actualizado_en  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4;

-- ---------------------------------------------------------------------
-- Chatbot: respuestas predefinidas y conversaciones guardadas
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS chatbot_respuestas (
    id              INT AUTO_INCREMENT PRIMARY KEY,
    tema            VARCHAR(50)  NOT NULL,
    palabras_clave  TEXT         NOT NULL,
    respuesta       TEXT         NOT NULL,
    ejemplo         VARCHAR(150) NULL,
    es_respaldo     TINYINT(1)   NOT NULL DEFAULT 0,
    UNIQUE KEY uq_chatbot_tema (tema)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4;

CREATE TABLE IF NOT EXISTS chat_mensajes (
    id            INT AUTO_INCREMENT PRIMARY KEY,
    usuario_id    INT NOT NULL,
    rol           ENUM('usuario', 'bot') NOT NULL,
    texto         TEXT NOT NULL,
    respuesta_id  INT NULL,
    creado_en     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_chat_usuario (usuario_id, id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4;

-- Base de conocimiento del chatbot
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('saludo', 'hola, buenas, buenos dias, buenas tardes, buenas noches, hey, que tal', '¡Hola! Soy el asistente de PonteChetado. Pregúntame sobre técnica de ejercicios, series y repeticiones, descanso o cómo armar tu entrenamiento.', NULL, 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('gracias', 'gracias, muchas gracias, vale, perfecto, genial, buena', '¡De nada! Si tienes otra duda de entrenamiento, aquí estoy.', NULL, 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('sentadilla', 'sentadilla, sentadillas, squat, sentadilla goblet', 'Sentadilla: pies al ancho de hombros con las puntas levemente hacia afuera. Baja llevando la cadera atrás y abajo, con las rodillas siguiendo la línea de los pies, la espalda neutra y el pecho arriba. Baja hasta que el muslo quede al menos paralelo al suelo y sube empujando con todo el pie. Error común: que las rodillas se vayan hacia adentro.', '¿Cómo hago una sentadilla?', 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('press_banca', 'press banca, press de banca, banca, bench, pecho plano, pecho', 'Press banca: junta las escápulas y llévalas hacia abajo, pies firmes en el suelo y una leve curva en la zona lumbar. Baja la barra controlada hasta la parte baja del pecho con los codos a unos 45° del cuerpo y empuja hacia arriba. Si vas a cargar pesado, usa un compañero o los seguros del rack.', '¿Cuál es la técnica del press banca?', 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('peso_muerto', 'peso muerto, deadlift, muerto', 'Peso muerto: barra sobre la mitad del pie y agárrala justo por fuera de las piernas. Espalda neutra, pecho arriba y brazos estirados. Empuja el suelo con las piernas y lleva la cadera adelante al final, con la barra siempre pegada al cuerpo. Nunca redondees la espalda baja: si pasa, el peso es demasiado.', '¿Cómo hago peso muerto sin dañarme la espalda?', 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('peso_muerto_rumano', 'peso muerto rumano, rumano, femoral, femorales, isquiotibiales', 'Peso muerto rumano: rodillas levemente flectadas y fijas. Lleva la cadera hacia atrás bajando la barra pegada a las piernas hasta sentir el estiramiento en los femorales (normalmente un poco bajo la rodilla). Espalda recta todo el tiempo y sube apretando los glúteos.', NULL, 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('dominadas', 'dominada, dominadas, pull up, pullup, chin up, jalon, jalon al pecho', 'Dominadas: agarre algo más ancho que los hombros y cuerpo firme. Tira llevando los codos hacia abajo y atrás hasta pasar el mentón sobre la barra, y baja controlado. Si todavía no puedes, usa banda elástica o máquina asistida, haz jalón al pecho o practica negativas (solo la bajada, lenta).', 'No puedo hacer dominadas, ¿qué hago?', 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('press_militar', 'press militar, militar, press de hombro, overhead, hombro, hombros', 'Press militar: de pie, barra a la altura de las clavículas, glúteos y abdomen apretados. Empuja la barra en línea recta sobre la cabeza, moviendo un poco la cabeza hacia atrás para dejarla pasar, y termina con los brazos estirados. No arquees la espalda baja para subir el peso.', NULL, 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('remo', 'remo, remo con barra, remo con mancuerna, remo en polea, espalda', 'Remo con barra: inclina el torso unos 45° con la espalda recta y las rodillas flectadas. Tira la barra hacia el ombligo llevando los codos atrás y juntando las escápulas, y baja controlado. Evita dar tirones con la espalda baja.', NULL, 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('gluteo', 'hip thrust, gluteo, gluteos, puente de gluteo, cola, trasero', 'Hip thrust: espalda alta apoyada en un banco y la barra sobre la cadera (usa una almohadilla). Empuja con los talones hasta que el torso quede paralelo al suelo y aprieta los glúteos arriba un segundo. Lleva el mentón hacia el pecho para no arquear la zona lumbar. También suman sentadilla, zancadas y peso muerto rumano.', '¿Cómo trabajo glúteos?', 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('zancadas', 'zancada, zancadas, lunge, estocada, estocadas', 'Zancadas: da un paso largo y baja hasta que ambas rodillas queden cerca de 90°, con la rodilla de atrás casi tocando el suelo. El torso va recto y la rodilla de adelante sigue la línea del pie. Empuja con el talón de adelante para volver.', NULL, 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('biceps', 'biceps, curl, curl con barra, curl martillo, brazo, brazos', 'Curl de bíceps: codos pegados al cuerpo y quietos. Sube el peso sin balancear el torso y bájalo lento (2 a 3 segundos). Si tienes que tirar con la espalda, el peso es demasiado. El curl martillo (agarre neutro) trabaja además el braquial y el antebrazo.', NULL, 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('triceps', 'triceps, extension de triceps, press frances, fondos, fondos en paralelas', 'Tríceps: en la extensión en polea mantén los codos fijos al costado y estira por completo abajo. En el press francés baja la barra hacia la frente moviendo solo los codos. En fondos, inclina un poco el torso y baja hasta unos 90° de codo, siempre sin dolor de hombro.', NULL, 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('abdomen', 'abdomen, abdominal, abdominales, core, plancha, six pack, crunch', 'Abdomen: combina ejercicios de flexión (crunch, elevación de piernas) con ejercicios de estabilidad (plancha). Con 2 a 3 veces por semana basta. Ojo: los abdominales se marcan sobre todo al bajar el porcentaje de grasa, no solo entrenándolos.', '¿Cómo marco el abdomen?', 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('hipertrofia', 'ganar musculo, hipertrofia, masa muscular, crecer, aumentar musculo, volumen muscular', 'Para ganar músculo: entre 8 y 12 repeticiones por serie (aunque de 6 a 20 también funciona), terminando a 1 a 3 repeticiones del fallo. Apunta a unas 10 a 20 series semanales por grupo muscular, repartidas en 2 sesiones, con 60 a 90 segundos de descanso. Lo más importante es ir subiendo peso o repeticiones con el tiempo.', '¿Cuántas repeticiones para ganar músculo?', 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('fuerza', 'fuerza, mas fuerte, 5x5, levantar mas peso, powerlifting, maximo', 'Para ganar fuerza: series de 3 a 6 repeticiones con peso alto en los ejercicios básicos (sentadilla, banca, peso muerto, press militar) y 2 a 3 minutos de descanso entre series. Sube el peso de a poco, por ejemplo 2,5 kg, cuando completes todas las series con buena técnica.', '¿Cómo gano más fuerza?', 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('descanso_series', 'descanso entre series, cuanto descanso, tiempo de descanso, descansar entre series, descanso', 'Descanso entre series: para fuerza, 2 a 3 minutos; para hipertrofia, 60 a 90 segundos; para resistencia o circuitos, 30 a 60 segundos. Si en la serie siguiente pierdes muchas repeticiones, descansa un poco más.', '¿Cuánto descanso entre series?', 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('frecuencia', 'cuantos dias, frecuencia, veces por semana, dias a la semana, entrenar todos los dias, cuantas veces', 'Con 3 a 4 días por semana se progresa muy bien. Lo ideal es trabajar cada grupo muscular unas 2 veces por semana y dejar al menos un día de descanso. En la app puedes elegir tus días en Rutinas → Arma tu rutina personalizada.', '¿Cuántos días a la semana debo entrenar?', 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('principiante', 'principiante, empezar, novato, primera vez, nunca he entrenado, por donde empiezo, recien empiezo', 'Si estás empezando: 3 días a la semana de cuerpo completo con ejercicios básicos (sentadilla, press, remo y peso muerto rumano) a 3 series de 10 a 12. Prioriza aprender la técnica con poco peso y súbelo de a poco. Puedes generar tu rutina en Rutinas → Arma tu rutina personalizada.', 'Soy principiante, ¿por dónde empiezo?', 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('calentamiento', 'calentar, calentamiento, antes de entrenar, warm up, entrar en calor', 'Calentamiento: 5 a 10 minutos de cardio suave, movilidad de las articulaciones que vas a usar y 2 a 3 series de aproximación del primer ejercicio con poco peso (por ejemplo, al 50% y al 70% del peso de trabajo).', '¿Cómo debo calentar?', 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('progresion', 'progresion, progresar, subir peso, cuando subir, estancado, estancamiento, no avanzo', 'Sobrecarga progresiva: cuando hagas todas las series con las repeticiones máximas del rango (por ejemplo 3×12) y buena técnica, sube el peso entre un 2% y un 5% y vuelve al rango bajo. Si llevas 2 a 3 semanas estancado, revisa tu sueño, alimentación y descanso, o haz una semana más liviana.', 'Estoy estancado, ¿qué hago?', 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('dolor_muscular', 'agujetas, dolor muscular, adolorido, me duele el musculo, dolor al otro dia, quedé adolorido', 'El dolor muscular que aparece 24 a 72 horas después de entrenar es normal, sobre todo al empezar o cambiar de rutina. Ayudan el movimiento suave, dormir bien y comer suficiente proteína. Mientras tanto puedes entrenar otro grupo muscular.', NULL, 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('lesion', 'lesion, lesionado, me lesione, dolor articular, me duele la rodilla, me duele la espalda, me duele el hombro, me duele la muneca, dolor agudo, pinchazo, crujido', 'Si sientes un dolor agudo, punzante o en una articulación, detén el ejercicio: no es lo mismo que el cansancio muscular. Si el dolor sigue, consulta a un profesional de la salud y pide a un entrenador del gimnasio que revise tu técnica.', NULL, 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('fallo', 'fallo, al fallo, rpe, rir, intensidad, hasta no poder', 'Entrenar al fallo es hacer repeticiones hasta no poder hacer otra con buena técnica. No hace falta en todas las series: quedarse a 1 a 3 repeticiones del fallo da casi los mismos resultados con menos fatiga. Deja el fallo para la última serie de ejercicios de aislamiento.', NULL, 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('cardio', 'cardio, correr, trotar, bicicleta, quemar grasa, bajar de peso, perder grasa, adelgazar', 'Para bajar grasa lo que más influye es la alimentación (gastar un poco más de lo que comes), y las pesas ayudan a no perder músculo. El cardio suma: 2 a 3 sesiones de 20 a 30 minutos por semana, idealmente después de las pesas o en días distintos.', '¿Cómo bajo grasa?', 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('alimentacion', 'proteina, proteinas, dieta, comer, alimentacion, suplementos, creatina, nutricion, calorias', 'Como guía general, para ganar músculo se suele recomendar entre 1,6 y 2,2 g de proteína por kilo de peso al día. Para un plan de alimentación o suplementos adaptado a ti, consulta a un nutricionista: este chat responde sobre entrenamiento y técnica.', NULL, 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('estiramientos', 'estirar, estiramiento, estiramientos, elongar, elongacion, movilidad, flexibilidad', 'Los estiramientos estáticos largos conviene dejarlos para después de entrenar o para otro momento. Antes de entrenar es mejor la movilidad dinámica: círculos de brazos, balanceos de piernas y sentadillas sin peso.', NULL, 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('recuperacion', 'dormir, sueno, recuperacion, recuperarme, sobreentrenamiento, cansado, agotado, deload', 'Dormir 7 a 9 horas es clave para recuperarte y ganar fuerza. Si te sientes agotado, rindes menos varias sesiones seguidas o duermes mal, haz una semana de descarga con la mitad de las series.', NULL, 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('series_reps', 'cuantas series, cuantas repeticiones, series y repeticiones, reps, repeticiones, series', 'Depende de tu objetivo: fuerza, 3 a 6 repeticiones; hipertrofia, 8 a 12; resistencia, 15 o más. En general, 3 a 4 series por ejercicio y 10 a 20 series por grupo muscular a la semana funcionan bien.', '¿Cuántas series y repeticiones hago?', 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('respiracion', 'respirar, respiracion, aire', 'Toma aire antes de la parte difícil del movimiento y bótalo al terminar el esfuerzo (al subir en la sentadilla o al empujar en el press). En levantamientos pesados, mantener el aire con el abdomen firme ayuda a proteger la espalda.', NULL, 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('app_xp', 'xp, experiencia, nivel, niveles, subir de nivel, puntos', 'En PonteChetado ganas 2 XP por cada serie que registras y 1 XP por cada 250 kg de volumen (peso × repeticiones). Cada nivel pide 50 XP más que el anterior, y tu avatar evoluciona al subir de nivel. Revisa tu avance en la pestaña Progreso.', '¿Cómo gano XP en la app?', 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('app_avatar', 'avatar, personaje, mi avatar', 'Tu avatar se edita en Perfil → Mi avatar. Eliges género, piel, peinado y colores, y a medida que subes de nivel gana muñequeras, hombros más anchos, cintillo, medalla y hasta corona.', NULL, 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('app_rutina', 'rutina personalizada, generar rutina, que rutina, armar rutina, crear rutina, rutina', 'Ve a Rutinas → Arma tu rutina personalizada: eliges tu objetivo (fuerza, hipertrofia, híbrido o salud) y los días que entrenas, y la app te arma una rutina para cada día con sus series y repeticiones.', NULL, 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('entrenador', 'entrenador, coach, profesor, ayuda presencial, alguien que me ayude', 'Si necesitas que alguien revise tu técnica, pide ayuda a un entrenador de tu gimnasio. Muy pronto podrás llamarlo directamente desde la app con el botón de ayuda.', NULL, 0) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);
INSERT INTO chatbot_respuestas (tema, palabras_clave, respuesta, ejemplo, es_respaldo) VALUES ('respaldo', '', 'No tengo una respuesta para eso. Solo respondo sobre ejercicios, técnica y entrenamiento. Prueba con algo como «¿Cómo hago una sentadilla?» o «¿Cuánto descanso entre series?».', NULL, 1) ON DUPLICATE KEY UPDATE palabras_clave = VALUES(palabras_clave), respuesta = VALUES(respuesta), ejemplo = VALUES(ejemplo), es_respaldo = VALUES(es_respaldo);

-- Revisión rápida
SELECT (SELECT COUNT(*) FROM chatbot_respuestas) AS respuestas_chatbot,
       (SELECT COUNT(*) FROM avatares) AS avatares_creados;
